        ["+10 health (the first 20 points give +1 each)"] = "+10 к здоровью (первые 20 единиц дают по +1)",
        ["+15 mana (the first 20 points give +1 each)"] = "+15 к мане (первые 20 единиц дают по +1)",
        [", +%s spell power (past your first 10 Intellect)"] = ", +%s к силе заклинаний (начиная с 11-й единицы интеллекта)",
        [", 1%% spell critical strike per %s Intellect"] = ", 1%% к критическому эффекту заклинаний за каждые %s ед. интеллекта",
