        ["+%.2f mana and +%.2f health per 5 sec while not casting"] = "+%.2f к мане и +%.2f к здоровью раз в 5 сек. вне боя с применением заклинаний",
        ["mana and health regeneration, scaling with your level and Intellect"] = "восполнение маны и здоровья, растущее с уровнем и интеллектом",
        [" AP"] = " СА", [" SP"] = " СЗ", ["%% crit"] = "%% крит.", ["%% spell crit"] = "%% крит. закл.", ["/5s"] = "/5с",
        [" attack power"] = " к силе атаки", [" spell power"] = " к силе заклинаний",
        ["%% critical strike"] = "%% к критическому удару", ["%% spell critical strike"] = "%% к крит. эффекту заклинаний", [" per 5 sec"] = " раз в 5 сек.",
        [" melee"] = " в ближнем бою", [" ranged"] = " в дальнем бою", [" block value"] = " к показателю блока",
        [" armor"] = " к броне", ["dodge (%.2f%% total)"] = "уклонение (всего %.2f%%)", ["dodge"] = "уклонение",
        [" health"] = " к здоровью", [" mana"] = " к мане", ["mana and health regeneration"] = "восполнение маны и здоровья",
        ["|cffffd100Ability Essence (AE)|r buys abilities. |cffffd100Talent Essence (TE)|r buys talent ranks.\nYou start with |cff00ff00"] = "|cffffd100Эссенция способностей (ЭС)|r покупает способности. |cffffd100Эссенция талантов (ЭТ)|r покупает ранги талантов.\nВы начинаете с |cff00ff00",
        [" AE|r and earn |cff00ff00+"] = " ЭС|r и получаете |cff00ff00+",
        [" AE every level from "] = " ЭС за каждый уровень начиная с ", ["|r. |cff00ff00Talent Essence arrives from level "] = "|r. |cff00ff00Эссенция талантов даётся с уровня ",
        [", +"] = ", +", [" a level|r: "] = " за уровень|r: ", [" by level "] = " к уровню ",
        ["Abilities are priced by rarity: |cffffffff"] = "Стоимость способностей зависит от редкости: |cffffffff",
        ["|r / |cff1eff00"] = "|r / |cff1eff00", ["|r / |cff0070dd"] = "|r / |cff0070dd", ["|r / |cffa335ee"] = "|r / |cffa335ee", ["|r / |cffff8000"] = "|r / |cffff8000",
        ["|r AE from common to legendary. "] = "|r ЭС от обычной до легендарной. ",
        ["Each talent costs %d TE, whatever rank you take it to."] = "Каждый талант стоит %d ЭТ независимо от выбранного ранга.",
        ["Each talent rank costs %d TE, so a 5-rank talent costs %d TE in full."] = "Каждый ранг таланта стоит %d ЭТ, полный талант из 5 рангов обойдётся в %d ЭТ.",
        [" Any talent can be taken without the talents above it, and each tier opens at its level."] = " Любой талант можно взять без предыдущих талантов, если открыт его уровень.",
        ["Builds you follow from level 1 to %d. Pick one from the |cffffd100Archetypes|r button on this panel or at the Hero Advancement NPC. It replaces your build (abilities and talents refunded, free), then buys its abilities and talents for you as each becomes available. Everything it buys is a normal purchase, and you can stop following it at any time."] = "Архетипы задают развитие с 1-го по %d-й уровень. Выберите архетип кнопкой |cffffd100Архетипы|r на панели или у наставника героев. Он бесплатно заменит вашу сборку, вернув способности и таланты, а затем будет покупать их по мере открытия. Все покупки обычные; следование можно прекратить в любой момент.",
        ["|cff00ff00Level 1:|r %d random abilities to begin.\n|cff00ff00From level %d:|r one roll every level, alternating between an ability and a talent."] = "|cff00ff00Уровень 1:|r случайных способностей в начале: %d.\n|cff00ff00С уровня %d:|r один бросок каждый уровень, способности и таланты чередуются.",
        ["Rolls are weighted by rarity: a legendary is weighted %d against a common's %d, so most of what you are dealt is common and a legendary is a real find. A roll only ever gives you something you do not already own, and it never replaces anything you have."] = "Вероятность зависит от редкости: вес легендарной способности — %d, обычной — %d, поэтому чаще выпадает обычное, а легендарное — редкая удача. Вы получите только то, чего ещё нет, и бросок ничего не заменяет.",
        ["Rerolls are free below level %d. From level %d, every level grants %d reroll charges, spent on abilities or talents alike. Reroll from the roll reveal, or later from |cffffd100My Build|r with the circular arrow next to anything you own."] = "До уровня %d перебросы бесплатны. С уровня %d каждый уровень даёт %d заряда переброса для способностей или талантов. Перебрасывайте при показе результата или позже на вкладке |cffffd100Моя сборка|r круглой стрелкой рядом с нужным умением.",
        ["While your Starting Hand is open, a padlock holds an ability back from |cffffd100Roll Abilities|r, which rerolls everything unlocked at once. At level %d the padlocks come off: from then on you reroll one ability at a time, and only the one you choose."] = "Пока открыт начальный набор, замок сохраняет способность при |cffffd100Перебросе способностей|r, который меняет всё незакреплённое сразу. На уровне %d замки исчезают: дальше можно перебрасывать только выбранную способность.",
        ["Some rolls only offer abilities that share a class with something you already own. The chance starts at %d%% and climbs %d points every time you reroll, then resets when a synergy roll lands."] = "Некоторые броски предлагают способности того же класса, что и уже изученные. Вероятность начинается с %d%% и при каждом перебросе увеличивается на %d, затем сбрасывается после подходящего броска.",
        ["Anything you reroll cannot come back for the next %d rolls, about %d levels. If everything you could use is owned or on cooldown, the cooldowns lift so you always get something usable."] = "Переброшенная способность не выпадет в течение следующих %d перебросов (примерно %d уровней). Если всё подходящее уже изучено или на перезарядке, перезарядки сбрасываются, чтобы вы всегда получили доступный вариант.",
        ["One scroll rerolls an ability or a talent once your charges run out. Buy them from level %d at the Hero Advancement NPC or with |cffffd100Buy Scroll|r on this panel; the price rises with level."] = "Свиток перебрасывает способность или талант, когда заряды закончились. Покупайте его с уровня %d у наставника героев или кнопкой |cffffd100Купить свиток|r на панели; цена растёт с уровнем.",
        ["Below level %d, the dice crest at the top-left of this window reopens your Starting Hand."] = "До уровня %d нажмите на значок костей в левом верхнем углу окна, чтобы снова открыть начальный набор.",
        ["Every item is open to every Hero: class armor sets, every glyph, poisons, soul bags, quivers and relics. The Hero Advancement NPC also sells classless items with stat mixes no class had, by level, and Hero heirlooms that grow with you from 1 to %d. Both drop in the world as well."] = "Любой герой может использовать любые предметы: классовые комплекты брони, символы, яды, сумки душ, колчаны и реликвии. Наставник героев продаёт по уровням бесклассовые предметы с новыми сочетаниями характеристик и фамильное снаряжение героя, растущее вместе с ним с 1-го по %d-й уровень. Эти предметы также можно найти в мире.",
        ["At level %d, start a new life with a rank that stays."] = "На уровне %d начните новую жизнь с постоянным рангом.",
        ["At level %d the |cffffd100Rebirth|r button starts you over at level 1, at your race's starting area, on the same path."] = "На уровне %d кнопка |cffffd100Перерождение|r вернёт вас на 1-й уровень в стартовую область вашей расы, сохранив выбранный путь.",
        ["Each Rebirth raises a |cffffd100rank|r that is yours for good:\n   |cff00ff00+%d%% kill and dungeon XP|r for the first, +%d%% more for each after, up to +%d%%. Quest XP rises more gently.\n   |cff00ff00+%d%% to every primary stat|r per rank, up to +%d%%."] = "Каждое перерождение повышает постоянный |cffffd100ранг|r:\n   |cff00ff00+%d%% опыта за убийства и подземелья|r за первый ранг, затем ещё +%d%% за каждый, максимум +%d%%. Опыт за задания растёт медленнее.\n   |cff00ff00+%d%% ко всем основным характеристикам|r за ранг, максимум +%d%%.",
        ["A run is a life under one rule, on your own path. Challenge runs start before level %d. Pick a challenge, read its rule, go."] = "Испытание — это жизнь по одному правилу на выбранном вами пути. Начните испытание до уровня %d. Выберите его, прочитайте правило и отправляйтесь.",
        ["|cffffd100Running out|r ends the run: the rule lifts and you keep everything. A Rebirth ends a run too. |cffffd100Reaching %d|r with a life left finishes it. Your first finish of a challenge pays its gold, its title, and an ability no roll or shop can give, kept as an heirloom. Finish without a single death for |cffffd100the Unbroken|r, once per character."] = "|cffffd100Потеря всех жизней|r завершает испытание: правило снимается, а добыча остаётся у вас. Перерождение тоже завершает испытание. Достигните |cffffd100%d-го уровня|r с оставшейся жизнью, чтобы пройти его. За первое прохождение вы получите золото, звание и унаследованную способность, которую нельзя получить броском или купить. Пройдите без смертей и получите звание |cffffd100Непреклонный|r (один раз на персонажа).",
        ["Opens Hero Advancement. Shift-click for the Help / GM window."] = "Открывает развитие героя. Shift-клик открывает окно помощи и обращения к ГМ.",
        ["Pet Talents"] = "Таланты питомца",
        ["Your tamed beast's talents. Your own are in Hero Advancement."] = "Таланты приручённого зверя. Ваши таланты находятся в окне развития героя.",
        ["Elite World"] = "Элитный мир", ["Legion"] = "Легион", ["Pursued"] = "Преследование",
        ["Hourglass"] = "Песочные часы", ["Glass"] = "Хрупкость", ["Spiteful"] = "Злопамятность", ["Bloodpact"] = "Кровный договор",
        ["Berserker"] = "Берсерк", ["Ironman"] = "Железная воля", ["Big Game Hunter"] = "Большая охота", ["Dealt Hand"] = "Рука судьбы", ["Hardcore"] = "Хардкор",
        ["Sworn"] = "Связанная клятвой", ["Marked"] = "Помеченная", ["Sworn Nemesis"] = "Немезида, связанная клятвой",
        ["Bloodsworn"] = "Связанный кровной клятвой", ["Thrice-Victorious"] = "Трижды победивший", ["Twice-Victorious"] = "Дважды победивший",
        ["the Bloodmad"] = "Кровожадный", ["Ironhide"] = "Железношкурый", ["Spellbane"] = "Губитель чар",
        ["the Venomous"] = "Ядовитый", ["the Unyielding"] = "Несгибаемый", ["Packleader"] = "Вожак стаи",
        ["the Relentless"] = "Неумолимый", ["Hero-Slayer"] = "Гроза героев",
        ["plate"] = "латы", ["mail"] = "кольчуга", ["leather"] = "кожа", ["cloth"] = "ткань",
        ["Plate"] = "Латы", ["Mail"] = "Кольчуга", ["Leather"] = "Кожа", ["Cloth"] = "Ткань",
        ["Casting"] = "применение заклинаний", ["Attacks"] = "атаки", ["Dodge"] = "уклонение",
        ["Spell critical strike chance"] = "шанс критического эффекта заклинаний", ["Mana regeneration"] = "восполнение маны",
        ["slower"] = "медленнее", ["faster"] = "быстрее", [" slower"] = " медленнее", [" faster"] = " быстрее",
        ["Armor Weight"] = "Вес брони", ["You wear no armor that counts."] = "На вас нет учитываемой брони.",
        ["Your armor"] = "Ваша броня", ["now / full set"] = "сейчас / полный комплект", ["All together"] = "Общий эффект",
        ["   Hover the |cffffd100Armor Weight|r buff on your buff bar for this realm's numbers."] = "   Наведите курсор на эффект |cffffd100Вес брони|r на панели эффектов, чтобы увидеть значения этого мира.",
        ["2 nemeses"] = "2 немезиды",
        ["Open |cffffd100Stats|r and place your first points. More arrive every level, and moving them is free."] = "Откройте окно |cffffd100«Характеристики»|r и распределите первые очки. Новые очки даются с каждым уровнем, а перераспределять их можно бесплатно.",
        ["Everything here can also be done at the Hero Advancement NPC in every capital city, Dalaran and Shattrath. Open this panel with "] = "Всё это также можно сделать у наставника героев в любой столице, Даларане или Шаттрате. Откройте эту панель командой ",
        ["|cffffff00/cw|r|cffaaaaaa, or the dice button on your minimap. Rebind the key under Key Bindings > Hero Advancement.|r"] = "|cffffff00/cw|r|cffaaaaaa или нажмите кнопку с костями на мини-карте. Переназначить клавишу можно в разделе «Назначение клавиш» > «Развитие героя».|r",
        ["|cffffd100Ability Essence (AE)|r buys abilities. |cffffd100Talent Essence (TE)|r buys talent ranks.\nYou start with |cff00ff00"] = "За |cffffd100эссенцию способностей (ЭС)|r покупают способности, а за |cffffd100эссенцию талантов (ЭТ)|r — ранги талантов.\nВ начале у вас есть |cff00ff00",
        [" AE|r and earn |cff00ff00+"] = " ЭС|r, а начиная с уровня |cff00ff00",
        [" AE every level from "] = " ЭС за каждый уровень, начиная с ",
        ["|r. |cff00ff00Talent Essence arrives from level "] = "|r. |cff00ff00Эссенция талантов начисляется с уровня ",
        [", +"] = ", по ",
        [" a level|r: "] = " за уровень|r: ",
        ["A roll never raises a rank you already hold. To push a talent higher, reroll it and stake |cffffd100Reroll Scrolls|r on it. The reroll costs its charge as usual and trades the talent for a new one; every extra scroll you stake buys a chance to keep it and raise its rank instead, possibly by more than one. If the stake fails the scrolls are spent and the talent is traded away. Use the circular arrow beside a talent in |cffffd100My Build|r."] = "Бросок не повышает ранг таланта, который у вас уже есть. Чтобы повысить его, перебросьте талант и поставьте на него |cffffd100свитки переброса|r. Переброс расходует заряд как обычно и заменяет талант новым; каждый дополнительный свиток даёт шанс сохранить прежний талант и повысить его ранг, возможно сразу на несколько ступеней. Если ставка не сыграет, свитки пропадут, а талант будет заменён. Нажмите круглую стрелку рядом с талантом во вкладке |cffffd100«Моя сборка»|r.",
        ["You carry mana, rage and energy at once, and each spell draws its own. The extra bars sit under your player frame and remember where you drag them. |cffffd100Settings|r on this panel picks which to show, including runes and runic power; |cffffd100/cwbars|r toggles them all. Combo points show on your target's frame, as they do for a Rogue."] = "У вас одновременно есть мана, ярость и энергия, и каждое заклинание расходует свой ресурс. Дополнительные полосы находятся под рамкой персонажа и остаются там, куда вы их перетащили. В разделе |cffffd100«Настройки»|r этой панели можно выбрать отображаемые ресурсы, включая руны и силу рун; команда |cffffd100/cwbars|r переключает все полосы. Очки серии приёмов отображаются на рамке цели, как у разбойника.",
        ["You get points every level to spend across Strength, Agility, Stamina, Intellect and Spirit, and moving them is free at any time. Open |cffffd100Stats|r and hover a stat to see what it is doing for you right now. Each point gives:\n"] = "С каждым уровнем вы получаете очки для распределения между силой, ловкостью, выносливостью, интеллектом и духом. Перераспределять их можно бесплатно в любое время. Откройте |cffffd100«Характеристики»|r и наведите курсор на параметр, чтобы увидеть его эффект. Каждое очко даёт:\n",
        ["Mana regeneration pauses for 5 seconds after you cast; Meditation, Arcane Meditation and Intensity let some of it continue."] = "Восполнение маны прекращается на 5 секунд после применения заклинания; таланты «Медитация», «Чародейская медитация» и «Напряжённость» позволяют частично сохранить его.",
        ["An ability that only works in a stance or form brings that form, and one that needs others brings those: Rend and Charge bring Battle Stance, Cat Form brings Claw and Prowl, Tame Beast brings Call Pet, Revive Pet, Feed Pet and Dismiss Pet. These extras are free, are not one of your rolls, and leave when nothing you own needs them."] = "Способность, работающая только в стойке или облике, автоматически даёт нужную стойку или облик; зависимые способности тоже добавляются: «Рассечение» и «Рывок» дают «Боевую стойку», «Облик кошки» — «Цапнуть» и «Крадущийся зверь», а «Укротить зверя» — команды призыва, воскрешения, кормления и отзыва питомца. Эти способности бесплатны, не расходуют броски и удаляются, когда они больше не нужны вашим способностям.",
        ["Death Knight spells strike for double on a critical, Flame Shock and Immolate can crit over time, Chaos Bolt goes through absorbs, and feral attack power works in Cat and Bear form. Nothing to buy or roll for."] = "Заклинания рыцаря смерти наносят двойной критический урон; «Огненный шок» и «Жертвенный огонь» могут критовать периодическим уроном; «Хаос-болт» пробивает поглощение урона, а сила атаки в облике кошки и медведя работает для специализации «Сила зверя». Ничего покупать или выбрасывать не нужно.",
        ["A talent that improves all of its class's abilities of one kind improves every ability of that kind, whichever class it comes from. Fire Power makes every Fire spell hit harder, Impale makes every melee strike crit harder, and Spiritual Healing strengthens every direct Holy heal. A talent that names particular spells, such as Improved Fireball, improves only those."] = "Талант, усиливающий все способности своего класса определённого типа, действует на любую такую способность, независимо от её класса. «Сила огня» усиливает все огненные заклинания, «Пронзание» — критические удары в ближнем бою, а «Духовное исцеление» — прямое исцеление светлой магией. Талант с названием конкретных заклинаний, например «Улучшенный огненный шар», усиливает только их.",
        ["Cost, cooldown, cast time, range, duration and values show what your build gives, talents from other classes included. An action button lights up only when you can pay what it costs."] = "В подсказках указаны стоимость, перезарядка, время применения, дальность, длительность и сила эффекта с учётом вашей сборки и талантов других классов. Кнопка способности подсвечивается, только если у вас хватает ресурсов на её применение.",
        ["Reroll or unlearn Summon Imp and the imp is dismissed. Reroll Tame Beast away and the beast is stabled; own it again and the same beast returns. A tamed beast's pet talents open from the stock Talents button."] = "Перебросьте или удалите «Призыв беса» — и бес исчезнет. Перебросьте «Укротить зверя» — питомец отправится в стойло; получите способность снова — и вернётся тот же зверь. Окно талантов питомца открывается стандартной кнопкой «Таланты».",
        ["Abilities that belong to no class, and a Hero talent tree of their own, in the pool beside everything else. The |cffffd100elemental variants|r are the physical strikes in seven elements, Fiery Heroic Strike to Holy Aimed Shot, each an ability of its own."] = "Способности, не принадлежащие ни одному классу, и отдельное древо талантов героя входят в общий список. |cffffd100Стихийные варианты|r — это физические удары семи стихий: от огненного «Героического удара» до светлого «Прицельного выстрела». Каждый из них считается отдельной способностью.",
        ["Spells that ask for a class item, such as Stoneskin Totem asking for an Earth Totem, cast without it. Reagents still apply."] = "Заклинания, которым обычно нужен классовый предмет, например «Тотем каменной кожи» с требованием земляного тотема, работают и без него. Требования к реагентам сохраняются.",
        ["Trained for you, free: Apprentice at 20, Journeyman at 40, flying at 60, Northrend flying at 68 and epic flying at 70. Mounts are bought and earned as normal. The class mounts (Warhorse, Charger, Felsteed, Dreadsteed, Acherus Deathcharger) are abilities, so they come from a roll or from Ability Essence."] = "Верховая езда обучается автоматически и бесплатно: ученик — на 20-м уровне, подмастерье — на 40-м, полёты — на 60-м, полёты в Нордсколе — на 68-м, быстрые полёты — на 70-м. Средства передвижения добываются и покупаются как обычно. Классовые ездовые животные (боевой конь, скакун, конь Скверны, кошмарный конь и погибельный конь Ахеруса) считаются способностями: их можно получить броском или за эссенцию способностей.",
        ["Any Hero may wear any armor, and each type is a trade. Each piece in the eight armor slots counts toward its type, so a mixed set gets a share of each. A full set of:"] = "Любой герой может носить любую броню, но у каждого её типа свои преимущества и недостатки. Предметы во всех восьми ячейках брони учитываются по типу, поэтому смешанный комплект получает часть эффектов каждого типа. Полный комплект даёт:",
        ["One |cffffd100Armor Weight|r buff on your buff bar stands for all of it. Hover it to see each type you wear, what it gives now beside a full set, and everything added together."] = "Один эффект |cffffd100«Вес брони»|r на панели эффектов показывает общий результат. Наведите на него курсор, чтобы увидеть типы надетой брони, их текущий вклад по сравнению с полным комплектом и суммарный эффект.",
        ["Auto Shot is taught while a bow, gun or crossbow is equipped, and taken back when it comes off. While you know it, Attack switches to Auto Shot whenever your target is out of melee reach, so a bow worn only for its stats would hold your swings back. Shoot and Throw are always yours, and |cffffd100Settings|r can keep Auto Shot off whatever you wear."] = "«Автоматическая стрельба» доступна, пока экипированы лук, ружьё или арбалет, и удаляется при их снятии. Пока способность доступна, кнопка атаки переключается на автоматическую стрельбу, если цель вне радиуса ближнего боя. Поэтому лук, надетый только ради характеристик, помешает атаковать вблизи. «Выстрел» и «Метание» доступны всегда, а в |cffffd100«Настройках»|r можно отключить автоматическую стрельбу независимо от экипировки.",
        ["You choose whether your quest progress is wiped, so every quest pays XP again, or kept. Worn gear goes into your bags, or to your mailbox if they are full. Your gold, bank, reputation, riding and flight paths stay."] = "Вы можете сбросить прогресс заданий, чтобы снова получать за них опыт, или сохранить его. Надетая экипировка попадёт в сумки, а если там нет места — на почту. Золото, банк, репутация, навык верховой езды и открытые маршруты полётов сохраняются.",
        ["The price rises with each rank."] = "Стоимость растёт с каждым рангом.",
        ["unlimited lives"] = "неограниченное число жизней",
        ["%d life out of %d remains"] = "Осталась %d жизнь из %d",
        ["%d lives (few) out of %d remain"] = "Осталось %d жизни из %d",
        ["%d lives out of %d remain"] = "Осталось %d жизней из %d",
        ["Unlimited"] = "Без ограничений",
        ["under a minute"] = "меньше минуты",
        ["%d minute"] = "%d минута",
        ["%d minutes (few)"] = "%d минуты",
        ["%d minutes"] = "%d минут",
        ["%s left"] = "Осталось: %s",
        ["Shards  |cff00ff00"] = "Осколки  |cff00ff00",
        ["     |cff00ff00extra life held|r"] = "     |cff00ff00есть дополнительная жизнь|r",
        ["Buy an extra life  (%d%s)"] = "Купить дополнительную жизнь  (%d%s)",
        ["Starts with |cffffffff%d life|r"] = "Начинает с |cffffffff%d жизнью|r",
        ["Starts with |cffffffff%d lives (few)|r"] = "Начинает с |cffffffff%d жизнями|r",
        ["Starts with |cffffffff%d lives|r"] = "Начинает с |cffffffff%d жизнями|r",
        ["Gold"] = "Золото",
        ["Title"] = "Звание",
        ["None"] = "Нет",
        ["Flawless run"] = "Безупречное прохождение",
        ["Shards"] = "Осколки",
        ["A death costs one life. Battlegrounds, arenas and duels cost nothing. Run out and the rule lifts; you keep your level, gear and build."] = "Каждая смерть отнимает одну жизнь. Смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, правило испытания перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["Reach level %d with %d Vengeance for"] = "Достигните %d-го уровня и накопите %d ед. мести, чтобы получить",
        ["Reach level %d for"] = "Достигните %d-го уровня, чтобы получить",
        ["Reach level %d with a life left for"] = "Достигните %d-го уровня, сохранив хотя бы одну жизнь, чтобы получить",
        ["|cffff8800You are on this run|r: %s."] = "|cffff8800Вы проходите это испытание|r: %s.",
        ["|cffff4444You are on %s|r: %s."] = "|cffff4444Вы проходите испытание «%s»|r: %s.",
        ["another challenge"] = "другое испытание",
        ["|cff00ff00You can start this now.|r"] = "|cff00ff00Вы можете начать это испытание.|r",
        ["|cffff4444Challenge runs start before level %d.|r"] = "|cffff4444Испытание можно начать до достижения %d-го уровня.|r",
        ["|cffffffffUnlimited lives|r on this challenge. A death never ends the run."] = "|cffffffffВ этом испытании нет ограничения жизней|r. Смерть не завершит его.",
        ["|cffffffffUnlimited lives|r on this challenge. A death never ends the run, and the extra life you hold waits for your next run."] = "|cffffffffВ этом испытании нет ограничения жизней|r. Смерть не завершит его, а дополнительная жизнь останется до следующего испытания.",
        ["|cffffffff%d life|r on this challenge. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизнь|r в этом испытании. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["|cffffffff%d life|r on this challenge%s. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизнь|r в этом испытании%s. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["|cffffffff%d lives|r on this challenge. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизней|r в этом испытании. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["|cffffffff%d lives|r on this challenge%s. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизней|r в этом испытании%s. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["|cffffffff%d lives (few)|r on this challenge. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизни|r в этом испытании. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        ["|cffffffff%d lives (few)|r on this challenge%s. A death costs one. Deaths in battlegrounds, arenas and duels cost nothing. Run out and the run ends: the rule lifts, and you keep your level, gear and build."] = "|cffffffff%d жизни|r в этом испытании%s. Каждая смерть отнимает одну жизнь; смерти на полях боя, аренах и во время дуэлей не учитываются. Когда жизни закончатся, испытание завершится, правило перестанет действовать, а уровень, экипировка и сборка сохранятся.",
        [", plus the extra life you hold"] = ", у вас также есть дополнительная жизнь",
        [" with %d Vengeance: the total level of the nemeses you slay."] = " с %d ед. мести — суммарным уровнем побеждённых немезид.",
        [" with at least one life left."] = " с хотя бы одной оставшейся жизнью.",
        ["Paid once, when you reach level %d%s"] = "Выдаётся один раз при достижении %d-го уровня%s",
        ["Finish without dying to also earn |cffe6cc80%s the Unbroken|r and a third more shards."] = "Завершите испытание без смертей, чтобы получить звание |cffe6cc80«Непоколебимый» (%s)|r и на треть больше осколков.",
        ["Finish without losing a life to also earn |cffe6cc80%s the Unbroken|r and a third more shards."] = "Завершите испытание, не потеряв ни одной жизни, чтобы получить звание |cffe6cc80«Непоколебимый» (%s)|r и на треть больше осколков.",
        ["Paid whenever the run ends, whether you finish or not. You earn one per level reached, and two per level past 60."] = "Осколки выдаются после любого завершившегося испытания, даже если вы не выполнили его цель: по одному за каждый достигнутый уровень и по два за каждый уровень выше 60-го.",
        ["You finished this challenge. Running it again pays shards, and the Unbroken title if you have not earned it."] = "Вы уже завершили это испытание. При повторном прохождении вы получите осколки и звание «Непоколебимый», если ещё не заработали его.",
        ["   |cffffd100Strength:|r "] = "   |cffffd100Сила:|r ",
        ["   |cffffd100Agility:|r "] = "   |cffffd100Ловкость:|r ",
        ["   |cffffd100Stamina:|r "] = "   |cffffd100Выносливость:|r ",
        ["   |cffffd100Intellect:|r "] = "   |cffffd100Интеллект:|r ",
        ["   |cffffd100Spirit:|r "] = "   |cffffd100Дух:|r ",
        ["Each challenge shows how many lives it gives. A death costs one, a fall or drowning included; deaths in battlegrounds and arenas, and while you are dueling, are free. Nemesis and Dealt Hand have unlimited lives. On Nemesis a death makes a nemesis instead, and the run finishes at level 80 with enough Vengeance."] = "В описании каждого испытания указано число жизней. Любая смерть отнимает одну жизнь, в том числе падение или утопление; смерти на поле боя, арене и во время дуэли не учитываются. У «Немезиды» и «Случайной руки» число жизней не ограничено. В испытании «Немезида» после смерти появляется немезида, а испытание завершается на 80-м уровне, если накоплено достаточно мести.",
        ["The hearts on the run badge at the top-right of this panel, and on the challenge tracker at the top of your screen. Hover either for your challenge's rule and rewards. The tracker also shows what your challenge is counting: the time left on the level on Hourglass, whether the hunter is on you on Pursued, your nemeses on Nemesis, and your health band on Berserker. Drag it to move it, click it for the challenge page, and hide or show it under Settings or with /cw tracker."] = "Сердца отображаются на значке испытания в правом верхнем углу этой панели и на его индикаторе вверху экрана. Наведите курсор на любой из них, чтобы увидеть правило и награды. Индикатор также показывает цель испытания: оставшееся время уровня в «Песочных часах», преследование охотником в «Преследуемом», ваших немезид в испытании «Немезида» и запас здоровья в «Берсерке». Перетащите индикатор, чтобы переместить его, нажмите для перехода к испытаниям. Его можно скрыть или показать в «Настройках» либо командой /cw tracker.",
        ["The creature that kills you becomes your nemesis: a rare elite above your level, there for you alone, waiting where it lives. It is on your minimap and has an arrow over its head. Each has strengths and a weakness, learned by fighting it; die to it again and it grows. |cffffd100Swear Vendetta|r makes a nemesis of a creature you choose, stronger and worth more. Slaying one pays experience and |cffffd100Vengeance|r, its level, and drops a trophy that works from your bags for the rest of the run. Finish the run and your best trophies merge into your |cffffd100Nemesis Charm|r, which you keep."] = "Существо, убившее вас, становится немезидой: это редкий элитный противник выше вашего уровня, доступный только вам и ожидающий в месте своего обитания. Он отмечен на мини-карте стрелкой над головой. У каждой немезиды есть сильные стороны и слабость, которые можно узнать в бою; если она убьёт вас снова, то станет сильнее. |cffffd100Клятва мести|r превращает выбранное вами существо в немезиду: она будет сильнее и ценнее. За убийство вы получите опыт и |cffffd100месть|r в размере её уровня, а также трофей, действующий из сумки до конца испытания. После завершения испытания лучшие трофеи объединятся в |cffffd100талисман немезиды|r, который останется у вас.",
        ["Every run pays them when it ends, finished or not: one per level reached, two per level past 60, and a third more for a run without a death. They buy an |cffffd100extra life|r for your next run, on the challenge page."] = "После любого испытания, завершённого или нет, вы получаете осколки: по одному за каждый достигнутый уровень, по два за каждый уровень выше 60-го и ещё треть от суммы за прохождение без смертей. На странице испытаний их можно обменять на |cffffd100дополнительную жизнь|r для следующего испытания.",
    },
}
